<?php
// Papan Sales. The WhatsApp Reader on the shop PC POSTs its board snapshot here (header X-Papan-Key),
// and gets back the last 35 days of orders (buyer phone, code, payment status) so it can tell who has paid.
// The key is generated by the Owner on /admin/papan.html; only its SHA-256 hash is stored.
require __DIR__ . '/_lib.php';

if ($_SERVER['REQUEST_METHOD'] !== 'POST') fail('POST sahaja.', 405);
$key = (string)($_SERVER['HTTP_X_PAPAN_KEY'] ?? '');
$hash = (string)setting('papan_key_hash', '');
if ($hash === '' || strlen($key) < 20 || !hash_equals($hash, hash('sha256', $key))) fail('Kunci sambungan tidak sah.', 401);

$raw = file_get_contents('php://input') ?: '';
if (strlen($raw) > 4000000) fail('Data terlalu besar.', 413);
$snap = json_decode($raw, true);
if (!is_array($snap) || !isset($snap['items']) || !is_array($snap['items'])) fail('Data tidak sah.');

// Stored compressed in settings (TEXT, max 64KB). If it is still too big, drop the oldest finished/quiet chats first.
$pack = function (array $s): string {
  $j = json_encode($s, JSON_UNESCAPED_UNICODE);
  return function_exists('gzencode') ? 'gz:' . base64_encode(gzencode($j, 6)) : 'js:' . $j;
};
$enc = $pack($snap);
while (strlen($enc) > 60000 && count($snap['items']) > 20) {
  $snap['items'] = array_slice($snap['items'], 0, (int)floor(count($snap['items']) * 0.85));
  $snap['dipotong'] = true;
  $enc = $pack($snap);
}
if (strlen($enc) > 60000) fail('Data terlalu besar.', 413);
set_setting('papan_data', $enc);
set_setting('papan_at', date('Y-m-d H:i:s'));

$rows = q('SELECT code,b_phone,pay_status,total,created_at,status FROM orders WHERE created_at>=?', [date('Y-m-d H:i:s', time() - 35 * 86400)])->fetchAll();
$orders = array_map(fn($o) => ['p' => norm_phone((string)$o['b_phone']), 'code' => $o['code'], 'pay' => $o['pay_status'],
  'total' => (float)$o['total'], 'created_at' => $o['created_at'], 'status' => $o['status']], $rows);
json_out(['ok' => true, 'orders' => $orders]);
